var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The original build should parse '1y' correctly to 31557600000
    // The patched build no longer handles 'y' units, so it should return undefined
    // We verify the original works, and the patched build does not
    const originalResult = ms('1y');
    assert.strictEqual(originalResult, 31557600000, 'Original build should parse "1y" correctly');

    const patchedResult = ms('1y');
    assert.strictEqual(patchedResult, undefined, 'Patched build should return undefined for "1y"');
  });
});

